<script setup>
import {ref,computed} from 'vue';import{decodeSellerPageData}from'../utils/sellerPageData';
const props=defineProps({pageData:{type:String,default:''}});const d=decodeSellerPageData(props.pageData);const search=ref(d.search||'');const filtered=computed(()=>!!(search.value||d.status));
</script>
<template><div class="seller-messages-page">
<div class="seller-page-heading"><div><h1>Messages</h1><p>Communicate with customers who contact your store.</p></div></div>
<div class="row g-4 mb-4"><div v-for="stat in d.stats" :key="stat.label" class="col-xl-3 col-md-6"><div class="seller-message-stat-card"><div class="seller-message-stat-icon" :class="stat.type"><i class="bi" :class="stat.icon"></i></div><div class="seller-message-stat-content"><span>{{stat.label}}</span><h3>{{stat.count}}</h3></div></div></div></div>
<div class="seller-messages-panel"><div class="seller-messages-filter"><div class="seller-message-tabs"><a :href="d.indexUrl" class="seller-message-tab" :class="{active:!d.status}">All <em>{{d.total}}</em></a><a :href="d.unreadUrl" class="seller-message-tab" :class="{active:d.status==='unread'}">Unread <em>{{d.unread}}</em></a><a :href="d.readUrl" class="seller-message-tab" :class="{active:d.status==='read'}">Read <em>{{d.read}}</em></a></div><form method="GET" :action="d.indexUrl" class="seller-messages-search-form"><input v-if="d.status" type="hidden" name="status" :value="d.status"><div class="seller-message-search"><i class="bi bi-search"></i><input v-model="search" type="text" name="search" placeholder="Search messages..."></div><button type="submit" class="seller-message-filter-button"><i class="bi bi-search"></i><span>Search</span></button><a v-if="filtered" :href="d.indexUrl" class="seller-message-reset-button"><i class="bi bi-x-lg"></i><span>Reset</span></a></form></div>
<div v-if="d.messages.length" class="seller-message-list"><a v-for="m in d.messages" :key="m.id" :href="m.url" class="seller-message-item" :class="{'is-unread':m.unread}"><div class="seller-message-avatar"><img v-if="m.photoUrl" :src="m.photoUrl" :alt="m.sender"><span v-else>{{m.initial}}</span><i v-if="m.unread" class="seller-message-avatar-dot"></i></div><div class="seller-message-content"><div class="seller-message-top"><div class="seller-message-sender"><strong>{{m.sender}}</strong><span v-if="m.unread" class="seller-message-new-badge">New</span></div><time><i class="bi bi-clock"></i>{{m.humanDate}}</time></div><div class="seller-message-subject">{{m.subject}}</div><p>{{m.preview}}</p><div class="seller-message-meta"><span><i class="bi bi-envelope"></i>{{m.email}}</span><span v-if="m.replies" class="has-replies"><i class="bi bi-reply"></i>{{m.replies}} {{m.replies===1?'reply':'replies'}}</span></div></div><div class="seller-message-arrow"><i class="bi bi-arrow-right"></i></div></a></div>
<div v-if="d.messages.length&&d.links.length>3" class="seller-messages-pagination"><nav aria-label="Pagination"><a v-for="(link,i) in d.links" :key="i" :href="link.url||undefined" :class="{active:link.active,disabled:!link.url}" v-html="link.label"></a></nav></div>
<div v-if="!d.messages.length" class="seller-messages-empty"><div class="seller-messages-empty-icon"><i class="bi bi-chat-left-text"></i></div><h5>No Messages Found</h5><p>You don't have any messages matching your current filters.</p><a v-if="filtered" :href="d.indexUrl" class="seller-message-filter-button seller-message-clear-filter"><i class="bi bi-arrow-counterclockwise"></i><span>Clear Filters</span></a></div>
</div></div></template>
